// Des: Job table: run one job by name and words
// Flo: job name > words > matching job function > Report
// I/O: Sess + job + words (caller) > Report (counts, lines)
// ===================================================================
const std = @import("std"); const sess = @import("ru-sess-ctxz.zig"); const rd = @import("ru-chat-read.zig"); const grp = @import("ru-chat-grou.zig"); const rec = @import("ru-reci-main.zig"); const cana = @import("ru-labl-cana.zig"); const acts = @import("ru-chat-acts.zig"); const boar = @import("ru-boar-acts.zig"); const cfile = @import("ru-chat-file.zig"); const snd = @import("ru-chat-send.zig"); const fnd = @import("ru-labl-find.zig"); const acct = @import("ru-acct-acts.zig");
const Spec = struct { name: []const u8, need: usize, ask: bool = false };
pub const SPECS = [_]Spec{ .{ .name = "read", .need = 0 }, .{ .name = "reply", .need = 0 }, .{ .name = "summ", .need = 0 }, .{ .name = "canary", .need = 0 }, .{ .name = "say", .need = 1 }, .{ .name = "send", .need = 2 }, .{ .name = "remind", .need = 3 }, .{ .name = "pin", .need = 1 }, .{ .name = "mute", .need = 1 }, .{ .name = "group", .need = 0, .ask = true }, .{ .name = "forward", .need = 2, .ask = true }, .{ .name = "react", .need = 3 }, .{ .name = "quote", .need = 3 }, .{ .name = "recall", .need = 2, .ask = true }, .{ .name = "delete", .need = 2, .ask = true }, .{ .name = "pinmsg", .need = 2 }, .{ .name = "download", .need = 2 }, .{ .name = "archive", .need = 1 }, .{ .name = "hide", .need = 1 }, .{ .name = "unread", .need = 1 }, .{ .name = "alias", .need = 1 }, .{ .name = "block", .need = 1, .ask = true }, .{ .name = "sticker", .need = 2 }, .{ .name = "file", .need = 2 }, .{ .name = "poll", .need = 4 }, .{ .name = "note", .need = 2 }, .{ .name = "label", .need = 2 }, .{ .name = "quick", .need = 2 }, .{ .name = "usequick", .need = 2 }, .{ .name = "friend", .need = 1, .ask = true }, .{ .name = "accept", .need = 1 }, .{ .name = "ignore", .need = 1 }, .{ .name = "reqaccept", .need = 1, .ask = true }, .{ .name = "reqignore", .need = 1 }, .{ .name = "rename", .need = 2 }, .{ .name = "addmember", .need = 2, .ask = true }, .{ .name = "delmember", .need = 2, .ask = true }, .{ .name = "deputy", .need = 2, .ask = true }, .{ .name = "leave", .need = 1, .ask = true }, .{ .name = "unfriend", .need = 1, .ask = true }, .{ .name = "logout", .need = 0, .ask = true }, .{ .name = "devices", .need = 0 }, .{ .name = "devout", .need = 1, .ask = true }, .{ .name = "notify", .need = 1 }, .{ .name = "lang", .need = 1 }, .{ .name = "storage", .need = 0 }, .{ .name = "help", .need = 0 }, .{ .name = "feedback", .need = 1, .ask = true }, .{ .name = "passwd", .need = 0 }, .{ .name = "profile", .need = 0 }, .{ .name = "cloud", .need = 1 } };
pub fn known(job: []const u8) bool { for (SPECS) |sp| { if (std.mem.eql(u8, sp.name, job)) return true; } return false; }
pub fn isAsk(job: []const u8) bool { for (SPECS) |sp| { if (std.mem.eql(u8, sp.name, job)) return sp.ask; } return false; }
fn join(aren: std.mem.Allocator, words: []const []const u8) ![]const u8 { return std.mem.join(aren, " ", words); }
fn one(done: bool) rec.Report { return if (done) .{ .sent = 1 } else .{ .prev = 1 }; }
fn readJob(ses: *sess.Sess, name: []const u8) !rec.Report { const sum: rd.Summ = if (name.len > 0) .{ .chats = 1, .newm = try rd.readChat(ses, name) } else try rd.readUnread(ses); var lines: std.ArrayList([]const u8) = .empty; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "read {d} chats, {d} new messages", .{ sum.chats, sum.newm })); return .{ .prev = sum.chats, .lines = lines.items }; }
fn cloudName(ses: *sess.Sess) ![]const u8 { const chats = try rd.listChats(ses); const ent = ses.reg.get("cloud_chat") orelse return error.NoElem; for (chats) |cht| { for (ent.vi) |nam| { if (std.ascii.eqlIgnoreCase(nam, cht.name)) return cht.name; } for (ent.en) |nam| { if (std.ascii.eqlIgnoreCase(nam, cht.name)) return cht.name; } } return error.NoElem; }
fn actOf(job: []const u8) ?acts.Act { const map = [_]struct { n: []const u8, a: acts.Act }{ .{ .n = "react", .a = .react }, .{ .n = "recall", .a = .recall }, .{ .n = "delete", .a = .delme }, .{ .n = "pinmsg", .a = .pinm }, .{ .n = "download", .a = .down }, .{ .n = "archive", .a = .arch }, .{ .n = "hide", .a = .hide }, .{ .n = "unread", .a = .unre }, .{ .n = "alias", .a = .alia }, .{ .n = "block", .a = .bloc }, .{ .n = "sticker", .a = .stic } }; for (map) |ent| { if (std.mem.eql(u8, ent.n, job)) return ent.a; } return null; }
fn opOf(job: []const u8) ?boar.Op { const map = [_]struct { n: []const u8, o: boar.Op }{ .{ .n = "poll", .o = .poll }, .{ .n = "note", .o = .note }, .{ .n = "label", .o = .labl }, .{ .n = "quick", .o = .quik }, .{ .n = "usequick", .o = .qkus }, .{ .n = "friend", .o = .freq }, .{ .n = "accept", .o = .facc }, .{ .n = "ignore", .o = .fign }, .{ .n = "reqaccept", .o = .macc }, .{ .n = "reqignore", .o = .mign }, .{ .n = "rename", .o = .gren }, .{ .n = "addmember", .o = .gadd }, .{ .n = "delmember", .o = .grem }, .{ .n = "deputy", .o = .gdep }, .{ .n = "leave", .o = .glea }, .{ .n = "unfriend", .o = .unfr }, .{ .n = "profile", .o = .prof } }; for (map) |ent| { if (std.mem.eql(u8, ent.n, job)) return ent.o; } return null; }
fn argAt(arg: []const []const u8, idx: usize) []const u8 { return if (idx < arg.len) arg[idx] else ""; }
fn acctOf(job: []const u8) ?acct.Op { const map = [_]struct { n: []const u8, o: acct.Op }{ .{ .n = "logout", .o = .logo }, .{ .n = "devices", .o = .devl }, .{ .n = "devout", .o = .devo }, .{ .n = "notify", .o = .setn }, .{ .n = "lang", .o = .setl }, .{ .n = "storage", .o = .stor }, .{ .n = "help", .o = .help }, .{ .n = "feedback", .o = .feed }, .{ .n = "passwd", .o = .pwdz } }; for (map) |ent| { if (std.mem.eql(u8, ent.n, job)) return ent.o; } return null; }
fn acctJob(ses: *sess.Sess, op: acct.Op, arg: []const []const u8) !rec.Report { const word = if (op == .feed) try join(ses.aren, arg) else argAt(arg, 0); const out = try acct.run(ses, op, word); if (acct.isRead(op)) { var lines: std.ArrayList([]const u8) = .empty; try lines.append(ses.aren, out.text); return .{ .prev = 1, .lines = lines.items }; } return one(out.done); }
pub fn dispatch(ses: *sess.Sess, job: []const u8, arg: []const []const u8) !rec.Report { const aren = ses.aren; for (SPECS) |sp| { if (std.mem.eql(u8, sp.name, job) and arg.len < sp.need) return error.BadJob; }
if (std.mem.eql(u8, job, "read")) return readJob(ses, argAt(arg, 0));if (std.mem.eql(u8, job, "reply")) return rec.run(ses, .price); if (std.mem.eql(u8, job, "summ")) return rec.run(ses, .summ); if (std.mem.eql(u8, job, "canary")) return cana.run(ses, argAt(arg, 0)); if (std.mem.eql(u8, job, "say")) return rec.run(ses, try rec.parse(try join(aren, arg)));
if (std.mem.eql(u8, job, "send")) return rec.run(ses, .{ .send = .{ .chat = arg[0], .text = try join(aren, arg[1..]) } }); if (std.mem.eql(u8, job, "remind")) return rec.run(ses, .{ .remind = .{ .chat = arg[0], .whenz = arg[1], .titl = try join(aren, arg[2..]) } });
if (std.mem.eql(u8, job, "pin") or std.mem.eql(u8, job, "mute")) return one(try grp.chatAct(ses, if (job[0] == 'p') .pin else .mute, arg[0], "")); if (std.mem.eql(u8, job, "group")) return one(try grp.chatAct(ses, .grop, "", if (arg.len > 0) try join(aren, arg) else "")); if (std.mem.eql(u8, job, "forward")) return one(try grp.chatAct(ses, .forw, arg[0], arg[1]));
if (std.mem.eql(u8, job, "quote")) return one(try acts.doAct(ses, .quote, arg[0], arg[1], try join(aren, arg[2..]))); if (std.mem.eql(u8, job, "file")) { const out = try cfile.sendFile(ses, arg[0], arg[1]); return switch (out) { .sent => one(true), .dry => one(false), .dup => .{ .skip = 1 } }; }
if (std.mem.eql(u8, job, "cloud")) { const nam = try cloudName(ses); const out = try snd.sendText(ses, nam, try join(aren, arg)); return switch (out) { .sent => one(true), .dry => one(false), .dup => .{ .skip = 1 } }; }
if (actOf(job)) |act| { const extra = if (act == .react or act == .stic) argAt(arg, 2) else ""; const needle = if (acts.onMessage(act)) argAt(arg, 1) else ""; const ex = if (act == .stic) argAt(arg, 1) else extra; return one(try acts.doAct(ses, act, arg[0], needle, ex)); }
if (opOf(job)) |op| { const chat_first = switch (op) { .poll, .note, .labl, .qkus, .gren, .gadd, .grem, .gdep, .glea, .unfr => true, else => false }; if (chat_first) { const rest = if (op == .note or op == .gren) try join(aren, arg[1..]) else argAt(arg, 1); return one(try boar.run(ses, op, arg[0], rest, argAt(arg, 2), argAt(arg, 3))); } if (op == .prof) return one(try boar.run(ses, op, "", "", "", "")); const body = if (op == .quik) try join(aren, arg[1..]) else ""; return one(try boar.run(ses, op, "", arg[0], body, "")); }
if (acctOf(job)) |op| return acctJob(ses, op, arg);
return error.BadJob; }
